<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Maze Discovery — 24 Explorer Bots</title>
<style>
  :root{
    --bg:#0e1116; --panel:#171c24; --ink:#e8edf5; --dim:#8b97a8;
    --accent:#57d9a3; --wall:#cfd8e6;
  }
  *{box-sizing:border-box}
  html,body{margin:0;padding:0;background:var(--bg);color:var(--ink);
    font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;}
  .wrap{max-width:980px;margin:0 auto;padding:18px 14px 40px;}
  h1{font-size:18px;margin:0 0 4px;letter-spacing:.5px}
  p.sub{margin:0 0 14px;color:var(--dim);font-size:12px;line-height:1.5}
  #hud{display:flex;flex-wrap:wrap;gap:10px;align-items:center;
    background:var(--panel);border:1px solid #232b36;border-radius:10px;
    padding:10px 12px;margin-bottom:12px;font-size:13px}
  #hud .box{background:#101620;border:1px solid #232b36;border-radius:7px;padding:5px 9px}
  #hud b{color:var(--accent);font-weight:700}
  button{font:inherit;font-size:13px;background:#26303d;color:var(--ink);
    border:1px solid #38465a;border-radius:7px;padding:6px 12px;cursor:pointer}
  button:hover{background:#31404f}
  button:active{transform:translateY(1px)}
  input[type=number]{font:inherit;font-size:13px;width:110px;background:#101620;
    color:var(--ink);border:1px solid #38465a;border-radius:7px;padding:6px 8px}
  #maze{display:inline-block;background:#0a0d12;border:1px solid #232b36;
    border-radius:12px;padding:6px;min-width:400px;min-height:400px}
